const assert = require('node:assert/strict');
const test = require('node:test');
const { loadConfig } = require('./config.cjs');

test('reads once with utf8 and preserves JSON values and compatible inputs', async () => {
  const defaults = { fallback: true };
  const inputs = ['null', 'false', '0', '""', '[]', '{"enabled":false}',
    null, false, 0, Buffer.from('[1,2]'), { toString: () => '"converted"' }];
  for (const input of inputs) {
    for (const asynchronous of [false, true]) {
      const calls = [];
      const result = await loadConfig('settings.json', (...args) => {
        calls.push(args);
        return asynchronous ? Promise.resolve(input) : input;
      }, defaults);
      assert.deepStrictEqual(result, JSON.parse(input));
      assert.deepStrictEqual(calls, [['settings.json', 'utf8']]);
    }
  }
});

test('only missing-file read failures return the exact defaults', async () => {
  const missing = Object.assign(new Error('missing'), { code: 'ENOENT' });
  for (const defaults of [{ fallback: true }, null, false, 0, '', undefined]) {
    for (const asynchronous of [false, true]) {
      let calls = 0;
      const result = await loadConfig('missing.json', () => {
        calls++;
        if (asynchronous) return Promise.reject(missing);
        throw missing;
      }, defaults);
      assert.strictEqual(result, defaults);
      assert.strictEqual(calls, 1);
    }
  }
});

test('preserves every other original read failure, including falsy failures', async () => {
  for (const failure of [new Error('read failed'), { code: 'EACCES' },
    undefined, null, false, 0, '', NaN]) {
    for (const asynchronous of [false, true]) {
      let calls = 0;
      await assert.rejects(loadConfig('settings.json', () => {
        calls++;
        if (asynchronous) return Promise.reject(failure);
        throw failure;
      }, {}), error => Object.is(error, failure));
      assert.strictEqual(calls, 1);
    }
  }
});

test('parse and conversion failures propagate even with code ENOENT', async () => {
  const failure = Object.assign(new Error('conversion failed'), { code: 'ENOENT' });
  for (const asynchronous of [false, true]) {
    for (const input of ['', '{', undefined, Symbol('invalid')]) {
      await assert.rejects(loadConfig('settings.json', () =>
        asynchronous ? Promise.resolve(input) : input, {}),
      input === undefined || typeof input === 'string' ? SyntaxError : TypeError);
    }
    const input = { toString() { throw failure; } };
    await assert.rejects(loadConfig('settings.json', () =>
      asynchronous ? Promise.resolve(input) : input, {}), error => error === failure);
  }
});

