const assert = require('node:assert/strict');
const test = require('node:test');
const { createCollection } = require('./collection.cjs');

test('distinct membership, current count, order, and initial count survive mutations', () => {
  const collection = createCollection(['b', 'a', 'b']);
  assert.strictEqual(collection.count, 2);
  assert.strictEqual(collection.initialCount, 2);
  assert.deepStrictEqual(collection.snapshot(), ['b', 'a']);
  collection.add('b');
  assert.strictEqual(collection.count, 2);
  assert.deepStrictEqual(collection.snapshot(), ['b', 'a']);
  collection.remove('missing');
  assert.strictEqual(collection.count, 2);
  collection.add('c');
  assert.strictEqual(collection.count, 3);
  collection.remove('b');
  assert.strictEqual(collection.count, 2);
  collection.add('b');
  assert.strictEqual(collection.count, 3);
  assert.deepStrictEqual(collection.snapshot(), ['a', 'c', 'b']);
  collection.reset(['z', 'z', 'x', 'y']);
  assert.strictEqual(collection.count, 3);
  assert.deepStrictEqual(collection.snapshot(), ['z', 'x', 'y']);
  collection.reset(['']);
  assert.strictEqual(collection.count, 1);
  assert.deepStrictEqual(collection.snapshot(), ['']);
  collection.reset();
  assert.strictEqual(collection.count, 0);
  assert.deepStrictEqual(collection.snapshot(), []);
  collection.remove('missing');
  assert.strictEqual(collection.count, 0);
  assert.strictEqual(collection.initialCount, 2);
});

test('input arrays and snapshots cannot mutate membership; instances are independent', () => {
  const initial = ['a'];
  const collection = createCollection(initial);
  const other = createCollection();
  initial.push('b');
  const snapshot = collection.snapshot();
  snapshot.push('c');
  assert.notStrictEqual(collection.snapshot(), collection.snapshot());
  assert.deepStrictEqual(collection.snapshot(), ['a']);
  const next = ['x', 'x'];
  collection.reset(next);
  next.length = 0;
  assert.deepStrictEqual(collection.snapshot(), ['x']);
  assert.strictEqual(collection.count, 1);
  assert.strictEqual(collection.initialCount, 1);
  assert.deepStrictEqual(other.snapshot(), []);
  assert.strictEqual(other.count, 0);
  assert.strictEqual(other.initialCount, 0);
  other.add('independent');
  assert.deepStrictEqual(collection.snapshot(), ['x']);
  assert.strictEqual(collection.count, 1);
  assert.strictEqual(other.count, 1);
  assert.strictEqual(other.initialCount, 0);
});

