const assert = require('node:assert/strict');
const { test } = require('node:test');
const { createCollection } = require('./collection.cjs');

test('distinct membership controls count and insertion order', () => {
  const collection = createCollection(['b', 'a', 'b']);
  assert.equal(collection.count, 2);
  assert.equal(collection.initialCount, 2);
  assert.deepEqual(collection.snapshot(), ['b', 'a']);
  collection.add('b');
  assert.equal(collection.count, 2);
  assert.deepEqual(collection.snapshot(), ['b', 'a']);
  collection.add('c');
  assert.equal(collection.count, 3);
  assert.deepEqual(collection.snapshot(), ['b', 'a', 'c']);
  collection.remove('missing');
  assert.equal(collection.count, 3);
  assert.deepEqual(collection.snapshot(), ['b', 'a', 'c']);
  collection.remove('a');
  assert.equal(collection.count, 2);
  assert.deepEqual(collection.snapshot(), ['b', 'c']);
  collection.remove('a');
  assert.equal(collection.count, 2);
  collection.add('a');
  assert.equal(collection.count, 3);
  assert.deepEqual(collection.snapshot(), ['b', 'c', 'a']);
  assert.equal(collection.initialCount, 2);
});

test('reset replaces membership, preserves initial count, and owns its inputs', () => {
  const initial = ['first', 'second', 'first'];
  const collection = createCollection(initial);
  initial.push('external');
  assert.deepEqual(collection.snapshot(), ['first', 'second']);
  const snapshot = collection.snapshot();
  assert.notStrictEqual(snapshot, collection.snapshot());
  snapshot.push('external');
  assert.deepEqual(collection.snapshot(), ['first', 'second']);
  const next = ['x', 'x', 'y', 'z'];
  collection.reset(next);
