exports.loadConfig = async (path, read, defaults) => {
  let contents;
  try { contents = await read(path, 'utf8'); }
  catch (error) {
    if (error?.code === 'ENOENT') return defaults;
    throw error;
  }
  return JSON.parse(contents);
};

