const assert = require('node:assert/strict');
const test = require('node:test');
const { loadConfig } = require('./config.cjs');

test('reads once with utf8 and preserves JSON.parse-compatible values', async () => {
  const defaults = { fallback: true };
  for (const input of ['null', 'false', '0', '""', '[1,"a"]', '{"ok":true}', null, false, 0, 12n, Buffer.from('42'), { toString: () => '"converted"' }]) {
    for (const asynchronous of [false, true]) {
      const calls = [];
      const result = await loadConfig('config.json', (...args) => {
        calls.push(args);
        return asynchronous ? Promise.resolve(input) : input;
      }, defaults);
      assert.deepEqual(result, JSON.parse(input));
      assert.deepEqual(calls, [['config.json', 'utf8']]);
    }
  }
});

test('only missing reads return the supplied defaults; other failures retain identity', async () => {
  const missing = Object.assign(new Error('missing'), { code: 'ENOENT' });
  for (const failure of [missing, Object.assign(new Error('denied'), { code: 'EACCES' }), false, 0, '', null, undefined, NaN]) {
    for (const asynchronous of [false, true]) {
      let calls = 0;
      const defaults = { fallback: true };
      const result = loadConfig('config.json', () => {
        calls++;
        if (asynchronous) return Promise.reject(failure);
        throw failure;
      }, defaults);
      if (failure === missing) assert.equal(await result, defaults);
      else await assert.rejects(result, error => Object.is(error, failure));
      assert.equal(calls, 1);
    }
  }
});

test('parse and conversion failures propagate even with ENOENT', async () => {
  const conversionFailure = Object.assign(new Error('conversion'), { code: 'ENOENT' });
  for (const asynchronous of [false, true]) {
    for (const input of ['{', undefined, Symbol('invalid')]) {
      await assert.rejects(loadConfig('config.json', () => asynchronous ? Promise.resolve(input) : input, {}), typeof input === 'symbol' ? TypeError : SyntaxError);
    }
    await assert.rejects(loadConfig('config.json', () => {
      const input = { toString() { throw conversionFailure; } };
      return asynchronous ? Promise.resolve(input) : input;
    }, {}), error => error === conversionFailure);
  }
});

