exports.createCollection = (initialIds = []) => {
  let ids = new Set(initialIds);
  const initialCount = ids.size;
  return {
    get count() { return ids.size; },
    initialCount,
    add(id) { ids.add(id); },
    remove(id) { ids.delete(id); },
    reset(next = []) { ids = new Set(next); },
    snapshot() { return [...ids]; },
  };
};

