const assert = require('node:assert/strict');
const test = require('node:test');
const { createCollection } = require('./collection.cjs');

test('distinct membership determines count while initialCount remains a snapshot', () => {
  const collection = createCollection(['b', 'a', 'b']);
  assert.equal(collection.count, 2);
  assert.equal(collection.initialCount, 2);
  assert.deepEqual(collection.snapshot(), ['b', 'a']);
  collection.add('a');
  assert.equal(collection.count, 2);
  collection.remove('missing');
  assert.equal(collection.count, 2);
  assert.deepEqual(collection.snapshot(), ['b', 'a']);
  collection.add('c');
  assert.equal(collection.count, 3);
  collection.remove('b');
  assert.equal(collection.count, 2);
  collection.add('b');
  assert.equal(collection.count, 3);
  assert.deepEqual(collection.snapshot(), ['a', 'c', 'b']);
  collection.reset(['z', 'z', 'x']);
  assert.equal(collection.count, 2);
  assert.deepEqual(collection.snapshot(), ['z', 'x']);
  collection.reset();
  collection.remove('absent');
  assert.equal(collection.count, 0);
  assert.deepEqual(collection.snapshot(), []);
  assert.equal(collection.initialCount, 2);
});

test('inputs, snapshots, and instances have independent membership', () => {
  const initial = ['a'];
  const collection = createCollection(initial);
  const other = createCollection();
  initial.push('b');
  const snapshot = collection.snapshot();
  snapshot.push('c');
  assert.notEqual(collection.snapshot(), collection.snapshot());
  assert.deepEqual(collection.snapshot(), ['a']);
  const replacement = ['d'];
  collection.reset(replacement);
  replacement.length = 0;
  assert.deepEqual(collection.snapshot(), ['d']);
  assert.equal(collection.count, 1);
  assert.equal(collection.initialCount, 1);
  assert.equal(other.count, 0);
  assert.equal(other.initialCount, 0);
  other.add('e');
  assert.deepEqual(other.snapshot(), ['e']);
  assert.deepEqual(collection.snapshot(), ['d']);
});

